mapper.select:
SELECT run_id, owner_key, request_id, state, generation
FROM grounded_run_control
WHERE run_id = #{plan.runId} AND owner_key = #{plan.owner.ownerKey}
  AND request_id = #{plan.requestId}
FOR UPDATE

SELECT evidence.id
FROM evidence_unit evidence
JOIN material_version version ON version.id = #{link.versionId}
     AND version.material_id = #{link.materialId}
JOIN material ON material.id = version.material_id
     AND material.owner_type = #{plan.owner.ownerType}
     AND material.owner_key = #{plan.owner.ownerKey}
     AND material.lifecycle_state = 'ACTIVE'
     AND (material.retention_class = 'RETAINED' OR material.expires_at > UTC_TIMESTAMP(3))
JOIN material_processing_revision revision ON revision.id = #{link.revisionId}
     AND revision.version_id = version.id AND revision.state = 'READY'
JOIN evidence_read_lease lease ON lease.owner_key = #{plan.owner.ownerKey}
     AND lease.run_id = #{plan.runId} AND lease.version_id = version.id
     AND lease.revision_id = revision.id AND lease.status = 'ACTIVE'
     AND lease.expires_at > UTC_TIMESTAMP(3)
WHERE evidence.id = #{link.evidenceId} AND evidence.version_id = version.id
  AND evidence.revision_id = revision.id AND evidence.status = 'ACTIVE'
LIMIT 1
FOR UPDATE

mapper.update:
UPDATE grounded_run_control
SET state = 'COMPLETED', completed_at = UTC_TIMESTAMP(3), updated_at = UTC_TIMESTAMP(3)
WHERE run_id = #{plan.runId} AND owner_key = #{plan.owner.ownerKey}
  AND request_id = #{plan.requestId} AND state = 'RUNNING'
  AND generation = #{plan.expectedRunGeneration}
